                j+=1
                if is_valid(i,j):
                    ans.append([i,j])
            # go bottom val times
            for _ in range(val):
                i+=1
                if is_valid(i,j):
                    ans.append([i,j])
            # go left val+1 times
            for _ in range(val+1):
                j-=1
                if is_valid(i,j):
                    ans.append([i,j])
            # go up val+1 times
            for _ in range(val+1):
                i-=1
                if is_valid(i,j):
                    ans.append([i,j])
            val+=2

