class Solution:
    def threeSumMulti(self, arr: List[int], target: int) -> int:
        arr.sort()
        count = 0
        for i in range(0, len(arr)-2):
            rem_sum = target - arr[i]
            hash_map = {}
            for j in range(i+1, len(arr)):
                if arr[j] > rem_sum:
                    break
                if rem_sum - arr[j] in hash_map:
                    count = count + hash_map[rem_sum-arr[j]]
                # update the hash_map
                hash_map[arr[j]] = hash_map.get(arr[j], 0) + 1
        return count % 1000000007

class Solution:
    def beautifulArray(self, N):
        result = [1]
        while len(result) < N:
            result = [i*2 - 1 for i in result] + [i*2 for i in result]
        return [i for i in result if i <= N]

class Solution(object):
    def reorderLogFiles(self, logs):
        self._seq=0
        def _sortBy(log):
            a=log.split(' ')
            logType,self._seq=('A',self._seq) if a[1].isalpha() else ('B',self._seq+1)
            return (logType," ".join(a[1:]),a[0]) if logType=='A' else (logType,self._seq)
        return sorted(logs,key=_sortBy)

